CREATE TABLE equipamentos_publicos (
    uid TEXT PRIMARY KEY,
    categoria TEXT NOT NULL,
    nome TEXT NOT NULL,
    logradouro TEXT,
    numero TEXT,
    bairro TEXT,
    latitude DOUBLE PRECISION NOT NULL,
    longitude DOUBLE PRECISION NOT NULL,
    fonte_json TEXT NOT NULL
);

ALTER TABLE visitas ADD COLUMN protocolo_e_ouve TEXT;
ALTER TABLE visitas ADD COLUMN ovitrampas_bloqueio TEXT;
ALTER TABLE bri_registros ADD COLUMN equipamento_uid TEXT REFERENCES equipamentos_publicos(uid);
ALTER TABLE recolhimentos ADD COLUMN logradouro TEXT;
ALTER TABLE recolhimentos ADD COLUMN quarteirao TEXT;
ALTER TABLE recolhimentos ADD COLUMN numero TEXT;

